import json,re
terms=['animation studio','college library','three-storey commercial building','high-school shooting','student suspects','22-storey building','Ras Laffan','internal explosion','three campaigners','Libyan detention','twin earthquakes','86 hours','skydiving-plane','skydiving plane','paramilitary offices','blast and gunfire','blast-and-gunfire','chip-packaging cluster','packaging cluster','U-15 World Cup','Mercury suspension','Damon Landor','Muk Choi Lau']
