 for line in f:
  try: arts.append(json.loads(line))
  except: pass
for term in terms:
 hits=[]
 for a in arts:
  title=a.get('title') or ''; txt=title+'\\n'+(a.get('content') or '')
  m=re.search(re.escape(term),txt,re.I)
